  const testCases = [0, -1, 1.5, 'string'];
  for (const qty of testCases) {
    const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty });
    assert.equal(addResult.ok, false, `Should reject qty ${qty}`);
    assert.equal(addResult.error, 'QTY_INVALID');
  }
});

test('addLine validates SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
